import app from 'flarum/admin/app';

/**
 * The statistics there are, in order: the built-in ones and any that other
 * extensions add with the Statistics extender. Each is labelled by
 * `flarum-statistics.admin.statistics.{name}_heading`.
 */
export default function statisticsEntities() {
  return app.forum.attribute('statisticsEntities') ?? ['users', 'discussions', 'posts'];
}
flarum.reg.add('flarum-statistics', 'admin/utils/statisticsEntities', statisticsEntities);